-- требование: FR-22, FR-23 (реестр типов и JSON Schema полей — данные, docs/DOC-TYPES.md)
create table doc_types (
    code text primary key,
    name text not null,
    signs text not null,
    schema jsonb not null,
    version int not null,
    sort int not null
);
insert into doc_types (code, name, signs, schema, version, sort) values ('PASSPORT_FOREIGN', 'Паспорт иностранного гражданина', 'Национальный паспорт иностранца: страница с фото, MRZ из двух строк по 44 символа, начинается с P<; слова PASSPORT, NATIONALITY, DATE OF BIRTH, название страны.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "properties": {"surname": {"type": ["string", "null"], "title": "Фамилия", "description": "Фамилия латиницей, как в визуальной зоне", "x-check": "name", "x-required": true}, "givenNames": {"type": ["string", "null"], "title": "Имя", "description": "Имя (имена) латиницей", "x-check": "name", "x-required": true}, "birthDate": {"type": ["string", "null"], "title": "Дата рождения", "description": "Дата рождения", "x-check": "date_birth", "x-required": true}, "sex": {"type": ["string", "null"], "title": "Пол", "description": "Пол: M или F", "x-check": "sex", "x-required": true}, "nationality": {"type": ["string", "null"], "title": "Гражданство", "description": "Гражданство (страна или код из 3 букв)", "x-check": "citizenship", "x-required": true}, "documentNumber": {"type": ["string", "null"], "title": "Номер паспорта", "description": "Номер паспорта", "x-check": "doc_number", "x-required": true}, "issueDate": {"type": ["string", "null"], "title": "Дата выдачи", "description": "Дата выдачи", "x-check": "date_issue", "x-required": false}, "expiryDate": {"type": ["string", "null"], "title": "Срок действия", "description": "Дата окончания срока действия", "x-check": "date_expiry", "x-required": true}, "issuingAuthority": {"type": ["string", "null"], "title": "Орган выдачи", "description": "Орган, выдавший паспорт", "x-check": "text", "x-required": false}}}', 1, 1);
insert into doc_types (code, name, signs, schema, version, sort) values ('PASSPORT_RF', 'Паспорт гражданина РФ', 'Внутренний паспорт РФ: «Российская Федерация», «Паспорт выдан», код подразделения NNN-NNN, серия и номер вида NN NN NNNNNN, место рождения.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "properties": {"surname": {"type": ["string", "null"], "title": "Фамилия", "description": "Фамилия", "x-check": "name", "x-required": true}, "givenName": {"type": ["string", "null"], "title": "Имя", "description": "Имя", "x-check": "name", "x-required": true}, "patronymic": {"type": ["string", "null"], "title": "Отчество", "description": "Отчество", "x-check": "name", "x-required": false}, "sex": {"type": ["string", "null"], "title": "Пол", "description": "Пол: МУЖ или ЖЕН", "x-check": "sex", "x-required": false}, "birthDate": {"type": ["string", "null"], "title": "Дата рождения", "description": "Дата рождения", "x-check": "date_birth", "x-required": true}, "birthPlace": {"type": ["string", "null"], "title": "Место рождения", "description": "Место рождения", "x-check": "text", "x-required": false}, "series": {"type": ["string", "null"], "title": "Серия", "description": "Серия паспорта, 4 цифры", "x-check": "passport_rf_series", "x-required": true}, "number": {"type": ["string", "null"], "title": "Номер", "description": "Номер паспорта, 6 цифр", "x-check": "passport_rf_number", "x-required": true}, "issueDate": {"type": ["string", "null"], "title": "Дата выдачи", "description": "Дата выдачи", "x-check": "date_issue", "x-required": true}, "departmentCode": {"type": ["string", "null"], "title": "Код подразделения", "description": "Код подразделения NNN-NNN", "x-check": "dept_code", "x-required": true}, "issuedBy": {"type": ["string", "null"], "title": "Кем выдан", "description": "Кем выдан", "x-check": "text", "x-required": true}}}', 1, 2);
insert into doc_types (code, name, signs, schema, version, sort) values ('MIGRATION_CARD', 'Миграционная карта', 'Миграционная карта / Migration card: серия и номер карты, дата въезда, цель визита (работа, частная, учёба…), срок пребывания, принимающая сторона.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "properties": {"fullName": {"type": ["string", "null"], "title": "ФИО", "description": "Фамилия и имя", "x-check": "name", "x-required": true}, "citizenship": {"type": ["string", "null"], "title": "Гражданство", "description": "Гражданство", "x-check": "citizenship", "x-required": true}, "series": {"type": ["string", "null"], "title": "Серия карты", "description": "Серия миграционной карты", "x-check": "text", "x-required": false}, "number": {"type": ["string", "null"], "title": "Номер карты", "description": "Номер миграционной карты", "x-check": "doc_number", "x-required": true}, "entryDate": {"type": ["string", "null"], "title": "Дата въезда", "description": "Дата въезда", "x-check": "date_entry", "x-required": true}, "visitPurpose": {"type": ["string", "null"], "title": "Цель визита", "description": "Цель визита", "x-check": "purpose", "x-required": true}, "stayUntil": {"type": ["string", "null"], "title": "Срок пребывания до", "description": "Срок пребывания до", "x-check": "date_until", "x-required": false}, "host": {"type": ["string", "null"], "title": "Принимающая сторона", "description": "Принимающая сторона", "x-check": "text", "x-required": false}}}', 1, 3);
insert into doc_types (code, name, signs, schema, version, sort) values ('WORK_PATENT', 'Патент на работу', 'Патент на осуществление трудовой деятельности: серия и номер патента, ФИО на кириллице и латинице, гражданство, документ, удостоверяющий личность, регион, профессия.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "properties": {"fullName": {"type": ["string", "null"], "title": "ФИО", "description": "Фамилия, имя, отчество кириллицей", "x-check": "name", "x-required": true}, "fullNameLatin": {"type": ["string", "null"], "title": "ФИО латиницей", "description": "Фамилия и имя латиницей", "x-check": "name", "x-required": false}, "birthDate": {"type": ["string", "null"], "title": "Дата рождения", "description": "Дата рождения", "x-check": "date_birth", "x-required": true}, "citizenship": {"type": ["string", "null"], "title": "Гражданство", "description": "Гражданство", "x-check": "citizenship", "x-required": true}, "series": {"type": ["string", "null"], "title": "Серия патента", "description": "Серия патента (2 цифры)", "x-check": "text", "x-required": true}, "number": {"type": ["string", "null"], "title": "Номер патента", "description": "Номер патента", "x-check": "doc_number", "x-required": true}, "passportNumber": {"type": ["string", "null"], "title": "Паспорт", "description": "Серия и номер документа, удостоверяющего личность", "x-check": "doc_number", "x-required": false}, "issueDate": {"type": ["string", "null"], "title": "Дата выдачи", "description": "Дата выдачи патента", "x-check": "date_issue", "x-required": true}, "region": {"type": ["string", "null"], "title": "Регион", "description": "Территория действия патента (субъект РФ)", "x-check": "text", "x-required": true}, "profession": {"type": ["string", "null"], "title": "Профессия", "description": "Профессия (специальность, должность)", "x-check": "text", "x-required": false}}}', 1, 4);
insert into doc_types (code, name, signs, schema, version, sort) values ('ARRIVAL_NOTICE', 'Уведомление о прибытии', 'Уведомление о прибытии иностранного гражданина в место пребывания (миграционный учёт), отрывная часть бланка: адрес места пребывания, срок пребывания до, принимающая сторона, отметка о приёме.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "properties": {"fullName": {"type": ["string", "null"], "title": "ФИО", "description": "Фамилия, имя иностранного гражданина", "x-check": "name", "x-required": true}, "citizenship": {"type": ["string", "null"], "title": "Гражданство", "description": "Гражданство", "x-check": "citizenship", "x-required": false}, "passportNumber": {"type": ["string", "null"], "title": "Паспорт", "description": "Серия и номер документа, удостоверяющего личность", "x-check": "doc_number", "x-required": false}, "address": {"type": ["string", "null"], "title": "Адрес пребывания", "description": "Адрес места пребывания", "x-check": "text", "x-required": true}, "stayUntil": {"type": ["string", "null"], "title": "Срок пребывания до", "description": "Заявленный срок пребывания до", "x-check": "date_until", "x-required": true}, "host": {"type": ["string", "null"], "title": "Принимающая сторона", "description": "Принимающая сторона (ФИО или организация)", "x-check": "text", "x-required": false}}}', 1, 5);
insert into doc_types (code, name, signs, schema, version, sort) values ('SNILS', 'СНИЛС', 'Страховое свидетельство обязательного пенсионного страхования или уведомление о регистрации в системе индивидуального (персонифицированного) учёта (АДИ-РЕГ); номер вида NNN-NNN-NNN NN.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "properties": {"fullName": {"type": ["string", "null"], "title": "ФИО", "description": "Фамилия, имя, отчество", "x-check": "name", "x-required": true}, "snils": {"type": ["string", "null"], "title": "Номер СНИЛС", "description": "Страховой номер индивидуального лицевого счёта NNN-NNN-NNN NN", "x-check": "snils", "x-required": true}, "birthDate": {"type": ["string", "null"], "title": "Дата рождения", "description": "Дата рождения", "x-check": "date_birth", "x-required": false}, "registrationDate": {"type": ["string", "null"], "title": "Дата регистрации", "description": "Дата регистрации", "x-check": "date_issue", "x-required": false}}}', 1, 6);
insert into doc_types (code, name, signs, schema, version, sort) values ('INN', 'ИНН', 'Свидетельство о постановке на учёт физического лица в налоговом органе: ИНН из 12 цифр, «Свидетельство о постановке на учёт», ФНС.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "properties": {"fullName": {"type": ["string", "null"], "title": "ФИО", "description": "Фамилия, имя, отчество", "x-check": "name", "x-required": true}, "inn": {"type": ["string", "null"], "title": "ИНН", "description": "ИНН физического лица, 12 цифр", "x-check": "inn", "x-required": true}, "birthDate": {"type": ["string", "null"], "title": "Дата рождения", "description": "Дата рождения", "x-check": "date_birth", "x-required": false}, "assignedDate": {"type": ["string", "null"], "title": "Дата постановки на учёт", "description": "Дата постановки на учёт", "x-check": "date_issue", "x-required": false}}}', 1, 7);
insert into doc_types (code, name, signs, schema, version, sort) values ('MEDICAL', 'Медицинское заключение', 'Медицинское заключение (об отсутствии заболеваний, медосвидетельствование, предварительный медосмотр) или полис ДМС: организация, номер, дата выдачи, срок действия.', '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "properties": {"fullName": {"type": ["string", "null"], "title": "ФИО", "description": "Фамилия, имя, отчество", "x-check": "name", "x-required": true}, "documentNumber": {"type": ["string", "null"], "title": "Номер документа", "description": "Номер заключения или полиса", "x-check": "doc_number", "x-required": false}, "issueDate": {"type": ["string", "null"], "title": "Дата выдачи", "description": "Дата выдачи", "x-check": "date_issue", "x-required": true}, "expiryDate": {"type": ["string", "null"], "title": "Срок действия", "description": "Действителен до", "x-check": "date_expiry", "x-required": false}, "organization": {"type": ["string", "null"], "title": "Организация", "description": "Медицинская организация или страховая компания", "x-check": "text", "x-required": true}}}', 1, 8);
